<?php
 namespace Pterodactyl\Services\Dezerx\Staff; use Throwable; use Illuminate\Support\Facades\Crypt; use Pterodactyl\Models\Dezerx\StaffMessage; use Pterodactyl\Models\Dezerx\StaffRequest; use Pterodactyl\Models\User; use Pterodactyl\Services\Dezerx\Settings; class Staff { public const SETTING_KEY = 'staff'; public const MIN_DURATION = 5; public const CEILING_DURATION = 43200; public const DEFAULTS = [ 'enabled' => false, 'auto_accept_default' => false, 'allow_staff_requests' => true, 'allow_queue' => true, 'allow_named' => true, 'allow_open_ended' => true, 'queue_ttl_minutes' => 1440, 'default_duration_minutes' => 120, 'max_duration_minutes' => 1440, 'max_extensions' => 3, 'extension_max_minutes' => 240, 'reminder_minutes' => 10, 'max_active_per_staff' => 3, 'max_staff_per_server' => 1, 'max_staff_accounts' => 25, 'cooldown_minutes' => 5, 'reason_min_length' => 20, 'require_2fa' => false, 'notify_email' => true, 'webhook_events' => [ 'opened' => true, 'claimed' => true, 'granted' => true, 'resigned' => true, 'declined' => true, 'resolved' => true, 'expiring' => false, 'expired' => false, 'message' => false, ], ]; public static function enabled(): bool { return (bool) self::setting('enabled', false); } public static function blob(): array { return Settings::get(self::SETTING_KEY) ?? []; } public static function write(array $values): void { Settings::put(self::SETTING_KEY, [...self::blob(), ...$values]); } public static function setting(string $key, mixed $fallback = null): mixed { return self::blob()[$key] ?? self::DEFAULTS[$key] ?? $fallback; } public static function number(string $key): int { return (int) self::setting($key, self::DEFAULTS[$key] ?? 0); } public static function flag(string $key): bool { return (bool) self::setting($key, self::DEFAULTS[$key] ?? false); } public static function maxDuration(): int { $value = self::number('max_duration_minutes'); return $value < self::MIN_DURATION ? self::MIN_DURATION : min($value, self::CEILING_DURATION); } public static function defaultDuration(): int { return self::clampDuration(self::number('default_duration_minutes')) ?? self::maxDuration(); } public static function clampDuration(?int $minutes): ?int { if ($minutes === null) { return null; } return max(self::MIN_DURATION, min($minutes, self::maxDuration())); } public static function openEndedAllowed(): bool { return self::flag('allow_open_ended'); } public static function webhookUrl(): ?string { $stored = self::blob()['webhook_url'] ?? null; if (!is_string($stored) || $stored === '') { return null; } try { $url = Crypt::decryptString($stored); } catch (Throwable) { return null; } return self::sanitiseWebhookUrl($url); } public static function storeWebhookUrl(?string $url): bool { $trimmed = trim((string) $url); if ($trimmed === '') { self::write(['webhook_url' => null]); return true; } $clean = self::sanitiseWebhookUrl($trimmed); if ($clean === null) { return false; } self::write(['webhook_url' => Crypt::encryptString($clean)]); return true; } public static function hasWebhook(): bool { return self::webhookUrl() !== null; } public static function sanitiseWebhookUrl(string $url): ?string { $url = trim($url); if ($url === '' || mb_strlen($url) > 300 || preg_match('/[\s<>"\']/', $url) === 1) { return null; } $parts = parse_url($url); if ($parts === false || !isset($parts['scheme'], $parts['host'], $parts['path'])) { return null; } if (mb_strtolower($parts['scheme']) !== 'https') { return null; } if (isset($parts['user']) || isset($parts['pass']) || isset($parts['port'])) { return null; } if (isset($parts['query']) || isset($parts['fragment'])) { return null; } $host = mb_strtolower($parts['host']); if (!in_array($host, ['discord.com', 'discordapp.com', 'canary.discord.com', 'ptb.discord.com'], true)) { return null; } if (!str_starts_with($parts['path'], '/api/webhooks/')) { return null; } if (preg_match('#^/api/webhooks/\d{5,32}/[A-Za-z0-9_-]{20,120}$#', $parts['path']) !== 1) { return null; } return 'https://' . $host . $parts['path']; } public static function webhookEvent(string $event): bool { $events = self::setting('webhook_events', self::DEFAULTS['webhook_events']); if (!is_array($events)) { return false; } return ($events[$event] ?? self::DEFAULTS['webhook_events'][$event] ?? false) === true; } public static function mentions(): array { $roles = self::blob()['webhook_role_id'] ?? ''; $role = preg_match('/^\d{5,32}$/', (string) $roles) === 1 ? (string) $roles : null; return [ 'role' => $role, 'pingStaff' => (bool) self::setting('webhook_ping_staff', false), ]; } public static function canAct(?User $user): bool { if ($user === null || !self::enabled()) { return false; } return $user->staff === true || $user->root_admin === true; } public static function isStaff(?User $user): bool { return $user !== null && $user->staff === true; } public static function accountsInUse(): int { return User::query()->where('staff', true)->count(); } public static function accountSlotsLeft(): int { $max = self::number('max_staff_accounts'); if ($max <= 0) { return PHP_INT_MAX; } return max(0, $max - self::accountsInUse()); } public static function payload(?User $user): ?array { if (!self::enabled() || $user === null) { return null; } return [ 'enabled' => true, 'staff' => $user->staff === true, 'admin' => $user->root_admin === true, 'queue' => self::flag('allow_queue'), 'named' => self::flag('allow_named'), 'staffRequests' => self::flag('allow_staff_requests'), 'openEnded' => self::openEndedAllowed(), 'defaultDuration' => self::defaultDuration(), 'maxDuration' => self::maxDuration(), 'minDuration' => self::MIN_DURATION, 'autoAcceptDefault' => self::flag('auto_accept_default'), 'autoAccept' => self::autoAcceptFor($user), 'maxExtensions' => self::number('max_extensions'), 'extensionMax' => self::number('extension_max_minutes'), 'reminderMinutes' => self::number('reminder_minutes'), 'seatsPerServer' => self::number('max_staff_per_server'), 'reasonMin' => self::number('reason_min_length'), 'messageMax' => StaffMessage::MAX_LENGTH, 'presets' => StaffPresets::describe(), ]; } public static function autoAcceptFor(User $user): bool { $stored = $user->dezerx_preferences['staffAutoAccept'] ?? null; if (is_bool($stored)) { return $stored; } return self::flag('auto_accept_default'); } public static function rememberAutoAccept(User $user, bool $value): void { $user->forceFill([ 'dezerx_preferences' => [...($user->dezerx_preferences ?? []), 'staffAutoAccept' => $value], ])->saveOrFail(); } public static function seatsInUse(int $serverId): int { return StaffRequest::query() ->where('server_id', $serverId) ->whereIn('status', StaffRequest::OPEN_STATUSES) ->count(); } public static function seatsLeft(int $serverId): int { $seats = self::number('max_staff_per_server'); if ($seats <= 0) { return 0; } return max(0, $seats - self::seatsInUse($serverId)); } } 